-- Run with the migration in a BEGIN/ROLLBACK transaction; no fixtures persist.
create or replace function pg_temp.assert(ok boolean,msg text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAILED: %',msg;end if;end$$;
create or replace function pg_temp.denied(ws uuid,action text,payload jsonb,k text) returns boolean language plpgsql as $$begin perform public.ops_command(ws,action,payload,k);return false;exception when others then return true;end$$;
select set_config('test.coord_user',(select id::text from auth.users order by created_at limit 1),true);
select set_config('test.coord_ws',gen_random_uuid()::text,true);
insert into public.workspaces(id,name,slug,owner_user_id) values(current_setting('test.coord_ws')::uuid,'Coordination rollback QA','coord-qa-'||gen_random_uuid(),current_setting('test.coord_user')::uuid);
insert into public.workspace_members(workspace_id,user_id,role) values(current_setting('test.coord_ws')::uuid,current_setting('test.coord_user')::uuid,'owner');
select set_config('request.jwt.claim.sub',current_setting('test.coord_user'),true);
set local role authenticated;
do $$declare ws uuid:=current_setting('test.coord_ws')::uuid;u uuid:=current_setting('test.coord_user')::uuid;out jsonb;job uuid;item uuid;customer uuid;booking uuid;begin
 perform public.ops_command(ws,'coordination_policy','{"enabled":true,"coordinate_enabled":true,"timezone":"UTC","business_start":"08:00","business_end":"18:00","business_days":[1,2,3,4,5],"enforce_hours":true,"travel_buffer":30}','coord-policy-1');
 perform pg_temp.assert(pg_temp.denied(ws,'coordination_policy','{"timezone":"Not/AZone"}','coord-bad-zone'),'bad timezone rejected');
 perform public.ops_command(ws,'employee_save',jsonb_build_object('user_id',u,'display_name','QA worker','skills',jsonb_build_array('HVAC'),'active',true),'coord-worker-1');
 insert into public.customers(workspace_id,first_name,email) values(ws,'QA coordination','coord@example.invalid') returning id into customer;
 out:=public.ops_command(ws,'inventory_save','{"name":"QA material","sku":"COORD","selling_price":20}','coord-item-1');item:=(out->>'id')::uuid;
 perform public.ops_command(ws,'stock_move',jsonb_build_object('id',item,'kind','receipt','quantity',10,'reason','QA opening stock'),'coord-stock-1');
 out:=public.ops_command(ws,'job_save',jsonb_build_object('title','QA service','customer_id',customer,'assigned_to',u,'labor_total',50),'coord-job-01');job:=(out->>'id')::uuid;
 perform public.ops_command(ws,'reserve_material',jsonb_build_object('id',job,'item_id',item,'quantity',2),'coord-reserve-1');
 out:=public.ops_command(ws,'job_transition',jsonb_build_object('id',job,'status','quoted'),'coord-quote-1');
 perform pg_temp.assert((out->>'revision')::integer=1,'quote revision 1');
 perform pg_temp.assert((select total=90 from public.ops_quote_revisions where job_id=job and revision=1),'quote immutable total');
 perform pg_temp.assert(pg_temp.denied(ws,'reserve_material',jsonb_build_object('id',job,'item_id',item,'quantity',1),'coord-no-amend'),'cannot change quoted materials');
 perform public.ops_command(ws,'estimate_revise',jsonb_build_object('id',job,'labor_total',75,'reason','QA customer revision'),'coord-revise-1');
 out:=public.ops_command(ws,'job_transition',jsonb_build_object('id',job,'status','quoted'),'coord-quote-2');
 perform pg_temp.assert((out->>'revision')::integer=2,'quote revision 2');
 perform pg_temp.assert((select count(*)=2 from public.ops_quote_revisions where job_id=job),'old quote retained');
 perform pg_temp.assert((select total=115 from public.ops_quote_revisions where job_id=job and revision=2),'revised quote amount');
 perform public.ops_command(ws,'job_transition',jsonb_build_object('id',job,'status','approved','approval_evidence','QA signed revision 2'),'coord-approve-1');
 perform public.ops_command(ws,'availability_save',jsonb_build_object('user_id',u,'starts_at','2030-01-07T11:00:00Z','ends_at','2030-01-07T12:00:00Z','available',false,'reason','QA leave'),'coord-leave-1');
 perform pg_temp.assert(pg_temp.denied(ws,'schedule_job',jsonb_build_object('id',job,'starts_at','2030-01-07T11:00:00Z','ends_at','2030-01-07T12:00:00Z'),'coord-unavail'),'worker unavailable rejected');
 perform pg_temp.assert(pg_temp.denied(ws,'schedule_job',jsonb_build_object('id',job,'starts_at','2030-01-07T05:00:00Z','ends_at','2030-01-07T06:00:00Z'),'coord-hours-1'),'business hours enforced');
 perform public.ops_command(ws,'schedule_job',jsonb_build_object('id',job,'starts_at','2030-01-07T09:00:00Z','ends_at','2030-01-07T10:00:00Z'),'coord-book-1');
 select id into booking from public.appointments where ops_job_id=job;
 perform pg_temp.assert(pg_temp.denied(ws,'estimate_revise',jsonb_build_object('id',job,'labor_total',100,'reason','QA booked revision'),'coord-book-revise'),'booked quote cannot change');
 perform public.ops_command(ws,'booking_update',jsonb_build_object('id',booking,'status','cancelled'),'coord-cancel-book');
 perform pg_temp.assert((select count(*)=1 from public.ops_quote_approvals where job_id=job),'recorded approval retained');
 perform public.ops_command(ws,'estimate_revise',jsonb_build_object('id',job,'labor_total',80,'reason','QA revision after cancellation'),'coord-final-revise');
 perform pg_temp.assert((select count(*)=1 from public.ops_quote_approvals where job_id=job),'revision does not erase approval history');
 perform public.ops_command(ws,'service_plan_save',jsonb_build_object('title','QA recurring maintenance','customer_id',customer,'assigned_to',u,'interval_days',30,'next_due',now()-interval '1 hour'),'coord-plan-1');
 perform public.ops_command(ws,'attachment_add',jsonb_build_object('job_id',job,'name','QA service photo','url','https://example.invalid/photo.jpg'),'coord-attach-1');
 perform public.ops_command(ws,'job_details',jsonb_build_object('id',job,'service_details',jsonb_build_object('equipment','QA furnace','serial','QA-01')),'coord-details-1');
 -- Leave a current quoted job for the draft worker; obsolete quote events must be skipped.
 out:=public.ops_command(ws,'job_save',jsonb_build_object('title','QA current quote','customer_id',customer,'labor_total',20),'coord-current-job');
 perform public.ops_command(ws,'job_transition',jsonb_build_object('id',(out->>'id')::uuid,'status','quoted'),'coord-current-quote');
 perform pg_temp.assert((select count(*)>0 from public.ops_business_events where workspace_id=ws),'events observed from actual records');
end$$;
reset role;
select le_ops.tick_business();
select le_ops.tick_business();
set local role authenticated;
do $$declare ws uuid:=current_setting('test.coord_ws')::uuid;d uuid;c uuid;begin
 perform pg_temp.assert((select count(*)=1 from public.ops_jobs where workspace_id=ws and recurring_plan_id is not null),'recurring service creates one reviewable job');
 perform pg_temp.assert((select count(*)>0 from public.ops_business_events where workspace_id=ws and status='completed' and result->>'outcome'='internal_actions_verified'),'backend tasks and drafts verified');
 perform pg_temp.assert(not exists(select 1 from public.ops_business_events where workspace_id=ws and status='dead_letter'),'no failed coordination fixture events');
 select id,customer_id into d,c from public.ops_communication_drafts where workspace_id=ws limit 1;
 perform pg_temp.assert(d is not null,'communication draft created');
 perform pg_temp.assert(pg_temp.denied(ws,'draft_review',jsonb_build_object('id',d,'status','approved'),'coord-no-consent'),'approval requires channel consent');
 insert into public.customer_contact_consent_events(workspace_id,customer_id,channel,decision,evidence_reference,actor_user_id) values(ws,c,'email','granted','QA documented permission',current_setting('test.coord_user')::uuid);
 perform public.ops_command(ws,'draft_review',jsonb_build_object('id',d,'status','approved'),'coord-draft-ok');
 perform pg_temp.assert((select delivery_status='not_sent' from public.ops_communication_drafts where id=d),'approved draft still not sent');
 insert into public.customer_contact_consent_events(workspace_id,customer_id,channel,decision,evidence_reference,actor_user_id,created_at) values(ws,c,'email','revoked','QA documented opt-out',current_setting('test.coord_user')::uuid,now()+interval '1 second');
 perform pg_temp.assert((select status='rejected' from public.ops_communication_drafts where id=d),'opt-out invalidates prior approval');
 perform public.ops_command(ws,'draft_review',jsonb_build_object('id',d,'status','approved'),'coord-draft-ok');
 perform pg_temp.assert((select status='rejected' from public.ops_communication_drafts where id=d),'replayed historical receipt cannot resurrect revoked approval');
 perform pg_temp.assert(pg_temp.denied(ws,'draft_review',jsonb_build_object('id',d,'status','approved'),'coord-reapprove-revoked'),'revoked consent blocks fresh approval');

 perform public.ops_command(ws,'coordination_policy','{"enabled":false,"coordinate_enabled":false,"timezone":"UTC","business_start":"08:00","business_end":"18:00","business_days":[1,2,3,4,5]}','coord-kill-1');
 perform pg_temp.assert(not exists(select 1 from public.ops_business_events where workspace_id=ws and status='pending'),'kill switch cancels pending internal actions');
end$$;
reset role;
select 'Business coordination quote, dispatch, consent, recurrence and backend tests passed' as result;
